// W3 отвечает на вопрос «система отвечает ХОРОШО?».
// На вопрос «сервисы ЖИВЫ?» отвечает отдельный граф — «Сторож локального стека».
// Проверки Qdrant и LM Studio нужны здесь не для тревоги, а чтобы не принять тишину
// сломанного сервиса за хорошие метрики: они помечают цифры недостоверными.
// Тревогу о смерти сервиса поднимает сторож — иначе администратор получит
// два сообщения об одном и том же и перестанет читать оба.
const alive = (name) => {
  try {
    const j = $(name).item.json || {};
    return !(j.error || j.__error);
  } catch (e) { return false; }
};

const qdrantOk = alive('1. Qdrant жив?');
const lmsOk    = alive('2. LM Studio жив?');

let m = {};
let pgOk = true;
try { m = $('3. Postgres — метрики за час').item.json || {}; if (m.error) pgOk = false; }
catch (e) { pgOk = false; }

// Пороги откалиброваны по факту, а не на глаз. Замер 21.08 по 77 обращениям за 12 часов:
// медиана 8,8 с, p95 38,5 с, максимум 54,3 с — столько стоит цепочка «роутер → агент →
// поиск по базе → валидатор» на локальных моделях. Прежний порог «максимум дольше 30 с»
// звенел бы каждый час на исправной системе, а ложная тревога хуже её отсутствия.
const MIN_OPS     = 5;      // на трёх обращениях статистики нет — про качество молчим
const ERR_MAX     = 3;      // ошибок за час
const AVG_LAT_MAX = 30000;  // средний ответ вдвое дольше обычного (обычно около 13 с)
const NEW_ESC_MAX = 5;      // новых неразобранных эскалаций за час — очередь к человеку растёт

const ops = Number(m.ops || 0);
const enoughData = ops >= MIN_OPS;
const problems = [];

if (!pgOk) problems.push('Postgres недоступен — метрики за час снять не удалось');

if (pgOk && enoughData) {
  if (Number(m.errors || 0) > ERR_MAX)
    problems.push(`ошибок за час: ${m.errors} (порог ${ERR_MAX})`);
  if (Number(m.avg_latency_ms || 0) > AVG_LAT_MAX)
    problems.push(`средний ответ ${(Number(m.avg_latency_ms) / 1000).toFixed(1)} с — вдвое дольше обычного`);
}

// Очередь к человеку смотрим всегда: она не зависит от того, сколько было обращений.
// Считаем НОВЫЕ за час, а не весь накопленный список: в накопленном лежат эскалации
// зачётных прогонов, их разбирают вручную, и по ним тревожить каждый час бессмысленно.
if (pgOk && Number(m.new_escalations_1h || 0) > NEW_ESC_MAX)
  problems.push(`новых эскалаций за час: ${m.new_escalations_1h} — очередь к человеку растёт`);

const dead = [!qdrantOk ? 'Qdrant' : null, !lmsOk ? 'LM Studio' : null].filter(Boolean);
const stale = dead.length
  ? `\n\n⚠️ _Не отвечают: ${dead.join(', ')} — цифры за час считайте недостоверными. Подробности пришлёт сторож._`
  : '';

const text =
  `📊 *W3 · метрики за час: требуется внимание*\n\n— ${problems.join('\n— ')}\n\n` +
  `_За последний час:_ обращений ${m.ops ?? '—'}, ошибок ${m.errors ?? '—'}, ` +
  `эскалаций ${m.escalated ?? '—'}, из кэша ${m.from_cache ?? '—'}, ` +
  `средняя задержка ${m.avg_latency_ms ?? '—'} мс, самая долгая ${m.max_latency_ms ?? '—'} мс.\n` +
  `Не разобрано эскалаций всего: ${m.open_escalations ?? '—'}. ` +
  `Не подтвердили визит сегодня: ${m.unconfirmed_today ?? '—'}.` + stale;

return [{ json: { ...m, qdrant_ok: qdrantOk, lmstudio_ok: lmsOk, postgres_ok: pgOk,
                  enough_data: enoughData,
                  alert: problems.length > 0, problems, alert_text: text } }];
